// 接口定义
public interface PayChannel {
    void pay(long cents);
}

// 实现类 1
public class WechatPay implements PayChannel {
    public void pay(long cents) {
        System.out.println("wechat pay " + cents);
    }
}

// 实现类 2
public class Alipay implements PayChannel {
    public void pay(long cents) {
        System.out.println("alipay pay " + cents);
    }
}

// META-INF/services/com.example.PayChannel 文件内容：
// com.example.WechatPay
// com.example.Alipay

import java.util.ServiceLoader;

public class SpiDemo {
    public static void main(String[] args) {
        // ServiceLoader 不是线程安全的，每次使用新建实例
        ServiceLoader<PayChannel> loader = ServiceLoader.load(PayChannel.class);
        for (PayChannel ch : loader) {
            ch.pay(100); // 迭代时才实例化，所有注册实现都会被创建
        }
        // 无法按名字只取 WechatPay，只能全量遍历
    }
}
